아래 Go 캐시 코드에서 race detector가 데이터 레이스를 잡았고 스테이징에서 한 번 데드락도 났어. 근본 원인을 분석하고, 락 구조를 다시 설계해서 고쳐줘. hits/misses 통계와 onEvict 콜백 동작은 유지해야 해.

```go
package cache

import (
    "sync"
    "time"
)

type entry struct {
    val     []byte
    expires time.Time
}

type Cache struct {
    mu      sync.RWMutex
    items   map[string]*entry
    hits    int
    misses  int
    onEvict func(key string)
}

func (c *Cache) Get(key string) ([]byte, bool) {
    c.mu.RLock()
    e, ok := c.items[key]
    c.mu.RUnlock()
    if !ok || time.Now().After(e.expires) {
        c.misses++
        if ok {
            c.mu.Lock()
            delete(c.items, key)
            c.mu.Unlock()
            c.onEvict(key)
        }
        return nil, false
    }
    c.hits++
    return e.val, true
}

func (c *Cache) Set(key string, val []byte, ttl time.Duration) {
    c.mu.Lock()
    defer c.mu.Unlock()
    if old, ok := c.items[key]; ok {
        old.val = val
        old.expires = time.Now().Add(ttl)
        return
    }
    c.items[key] = &entry{val: val, expires: time.Now().Add(ttl)}
}

func (c *Cache) janitor(interval time.Duration, stop <-chan struct{}) {
    t := time.NewTicker(interval)
    for {
        select {
        case <-t.C:
            c.mu.Lock()
            for k, e := range c.items {
                if time.Now().After(e.expires) {
                    delete(c.items, k)
                    c.onEvict(k)   // onEvict may call c.Get for metrics
                }
            }
            c.mu.Unlock()
        case <-stop:
            return
        }
    }
}
```

